        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
      }

      .status-message {
        min-height: 1.5rem;
        color: var(--danger-dark);
        font-weight: 700;
      }

      @media (max-width: 760px) {
        .app-shell {
          padding: 1rem;
        }

        .preview-layout {
          grid-template-columns: 1fr;
        }

        .image-frame {
          min-height: 18rem;
