      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
      }

      .status-message {
        min-height: 1.5rem;
        color: var(--danger-dark);
        font-weight: 700;
