  </head>
  <body>
    <div id="root"></div>

    <script>
      const image = {
        title: "Morning in the foothills",
        collection: "Landscape Library",
        date: "May 6, 2026",
        size: "4.8 MB"
      };

      function ImagePreview({ title, collection, date, size }) {
        return `
          <main class="app-shell">
            <article class="preview-card" aria-labelledby="image-title">
              <div class="preview-layout">
                <div class="image-frame" role="img" aria-label="Sunlit hills and trees in the morning"></div>
                <section class="details">
                  <div>
                    <p class="eyebrow">Image preview</p>
                    <h1 id="image-title">${title}</h1>
                    <p class="description">
                      Review this image before making changes to your library. Deleting it removes
                      the image from your saved collection.
                    </p>
                  </div>

                  <dl class="meta-list" aria-label="Image details">
                    <div>
                      <dt>Collection</dt>
                      <dd>${collection}</dd>
                    </div>
                    <div>
                      <dt>Date added</dt>
                      <dd>${date}</dd>
                    </div>
                    <div>
                      <dt>File size</dt>
                      <dd>${size}</dd>
                    </div>
                  </dl>

                  <div class="actions">
                    <button class="button button-primary" type="button">Download</button>
                    <button class="button button-danger trigger" type="button" aria-haspopup="dialog">
                      Delete image
                    </button>
                  </div>

                  <p class="status-message" role="status" aria-live="polite"></p>
                </section>
              </div>
            </article>
          </main>
        `;
      }

      function DeleteDialog({ title }) {
        return `
          <dialog aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-copy">
            <form class="dialog-content" method="dialog">
              <div class="dialog-icon" aria-hidden="true">!</div>
              <h2 class="dialog-title" id="delete-dialog-title">Delete this image?</h2>
              <p class="dialog-copy" id="delete-dialog-copy">
                This will permanently remove "${title}" from your library. This action cannot be undone.
              </p>
              <div class="dialog-actions">
                <button class="button button-secondary" value="cancel" type="submit">Keep image</button>
                <button class="button button-danger" value="delete" type="submit">Delete image</button>
              </div>
            </form>
          </dialog>
        `;
      }

      function App() {
        return `${ImagePreview(image)}${DeleteDialog(image)}`;
      }

      const root = document.querySelector("#root");
      root.innerHTML = App();

      const dialog = document.querySelector("dialog");
      const trigger = document.querySelector(".trigger");
      const statusMessage = document.querySelector(".status-message");

      trigger.addEventListener("click", () => {
        dialog.showModal();
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue === "delete") {
          statusMessage.textContent = "The image was deleted from your library.";
        }
      });
    </script>
  </body>
</html>
